import { createFeatureSelector, createSelector } from '@ngrx/store';
export const selectPortfolioState = createFeatureSelector('portfolio');
export const selectPortfolio = createSelector(selectPortfolioState, state => state.portfolio);
export const selectHoldings = createSelector(selectPortfolioState, state => state.holdings);
export const selectPortfolioIsLoading = createSelector(selectPortfolioState, state => state.isLoading);
export const selectPortfolioError = createSelector(selectPortfolioState, state => state.error);
export const selectPortfolioValue = createSelector(selectPortfolio, portfolio => portfolio?.totalValue || 0);
export const selectInvestedValue = createSelector(selectPortfolio, portfolio => portfolio?.investedValue || 0);
export const selectCurrentValue = createSelector(selectPortfolio, portfolio => portfolio?.currentValue || 0);
export const selectPortfolioPnL = createSelector(selectPortfolio, portfolio => portfolio?.totalPnL || 0);
export const selectPortfolioPnLPercent = createSelector(selectPortfolio, portfolio => portfolio?.totalPnLPercent || 0);
export const selectTodayPnL = createSelector(selectPortfolio, portfolio => portfolio?.todayPnL || 0);
export const selectTodayPnLPercent = createSelector(selectPortfolio, portfolio => portfolio?.todayPnLPercent || 0);
export const selectCash = createSelector(selectPortfolio, portfolio => portfolio?.cash || 0);
export const selectHoldingCount = createSelector(selectHoldings, holdings => holdings.length);
export const selectTradeCount = createSelector(selectPortfolio, portfolio => portfolio?.tradeCount || 0);
